39	// Percentages are applied as the exact fraction `amount * percent / 100`
40	// rather than via a float factor such as `amount * 0.1`, which drifts.
41	const percentOf = (percent: number, amount: number): number =>
42	  (amount * percent) / 100;
43	
44	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
45	const CURSE_SURCHARGE_PERCENT = 50;
46	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
47	const HIGH_ENCHANTMENT_THRESHOLD = 5;
48	
49	const firstInsuranceSurchargeOn = (policyBasePremium: number): number =>
50	  percentOf(FIRST_INSURANCE_SURCHARGE_PERCENT, policyBasePremium);
51	
52	const LOYALTY_DISCOUNT_PERCENT = 20;
53	const LOYALTY_YEARS_THRESHOLD = 2;
54	
55	const loyaltyDiscountOn = (
56	  policyBasePremium: number,
57	  customer: Customer,
58	): number =>
59	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
60	    ? percentOf(LOYALTY_DISCOUNT_PERCENT, policyBasePremium)
61	    : 0;
62	
63	// Surcharges attached to a single item are a percentage of that item's own
64	// base premium from the price list (never of the policy base premium).
65	const surchargeForItem = (item: Item): number => {
66	  const cursePercent = item.cursed ? CURSE_SURCHARGE_PERCENT : 0;
67	  const highEnchantmentPercent =
68	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
69	      ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT
70	      : 0;
71	  return percentOf(
72	    cursePercent + highEnchantmentPercent,
73	    BASE_PREMIUM_BY_TYPE[item.type],
74	  );
75	};
76	
77	const itemSurchargesOf = (items: Item[]): number =>
78	  items.reduce((total, item) => total + surchargeForItem(item), 0);
79	
80	const BLOCK_SIZE = 3;
81	const BLOCK_BASE_PREMIUM = 60;
82	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
83	
84	const countByType = (items: Item[]): Map<string, number> => {
85	  const counts = new Map<string, number>();
86	  for (const item of items) {
87	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
88	  }
89	  return counts;
90	};
91	
92	// A group of exactly BLOCK_SIZE alike components forms a block and is charged
93	// a flat BLOCK_BASE_PREMIUM instead of the per-item price list rate. Main
94	// items never form a block.
95	const basePremiumForAlikeItems = (type: string, count: number): number =>
96	  COMPONENT_TYPES.has(type) && count === BLOCK_SIZE
97	    ? BLOCK_BASE_PREMIUM
98	    : count * BASE_PREMIUM_BY_TYPE[type];
99	
100	const policyBasePremiumOf = (items: Item[]): number =>
101	  [...countByType(items)].reduce(
102	    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
103	    0,
104	  );
105	
106	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
107	  const results = scenario.steps.map((step) => {
108	    const policyBasePremium = policyBasePremiumOf(step.items);
109	    const premium =
110	      policyBasePremium +
111	      itemSurchargesOf(step.items) -
112	      loyaltyDiscountOn(policyBasePremium, scenario.customer) +
113	      firstInsuranceSurchargeOn(policyBasePremium) +
114	      PROCESSING_FEE;
115	    return { premium };
116	  });
117	
118	  return { results };
119	};
