export const runScenario = (scenario: Scenario): ScenarioOutcome => {
  const results = scenario.steps.map((step, quotesAlreadyProcessed) => {
    const policyBasePremium = policyBasePremiumOf(step.items);
    const premium =
      policyBasePremium +
      itemSurchargesOf(step.items) -
      loyaltyDiscountOn(policyBasePremium, scenario.customer) +
      firstInsuranceSurchargeOn(policyBasePremium) -
      followUpDiscountOn(policyBasePremium, quotesAlreadyProcessed) +
      PROCESSING_FEE;
    return { premium };
  });

const FOLLOW_UP_DISCOUNT_PERCENT = 15;

const followUpDiscountOn = (
  policyBasePremium: number,
  quotesAlreadyProcessed: number,
): number =>
  quotesAlreadyProcessed > 0
    ? percentOf(FOLLOW_UP_DISCOUNT_PERCENT, policyBasePremium)
    : 0;

// Surcharges attached to a single item
